import Foundation

/// Eine kurze Erklärung zu einer Katalog-Übung: Ablauf in zwei, drei Sätzen und der häufigste Fehler. Eigene Texte (ExerciseDB liefert nur die Bilder).
struct UebungsAnleitung: Equatable, Sendable {
    let ablauf: String
    let fehler: String
}

